// SPDX-License-Identifier: Apache-2.0
//! TLS for `war ui --lan` (OW-WAR-0139, U-002).
//!
//! TLS terminates in `war`, on the same blocking accept loop as the rest of
//! the server (OW-ADR-0014: no async), through `rustls` with the `ring`
//! provider — both already in the build through `ureq`.
//!
//! Two sources of a certificate, and the server says which it is using:
//!
//! - **operator** (U-002 option A): `--cert <pem> --key <pem>`, for example
//!   from `tailscale cert` or a local CA. A device that trusts that CA opens
//!   the page with no warning.
//! - **self-signed** (U-002 option B, the labelled fallback):
//!   `--self-signed` makes a P-256 key and a certificate for `--name`, kept
//!   in the per-user state directory (mode 0600) so its fingerprint is stable
//!   across restarts. Every device shows the browser's warning on first
//!   visit; the SHA-256 fingerprint is printed at the host and carried in the
//!   pairing link, for the human to compare (basis A-002).
//!
//! A handshake that fails — a plain-HTTP request to the LAN port included —
//! gets no HTTP response at all. The certificate's self-signature is a TLS
//! artefact; it is not an authority signature and no key here can make one.

use std::net::TcpStream;
use std::sync::Arc;
use std::time::{Duration, Instant};

use camino::{Utf8Path, Utf8PathBuf};
use rustls::{ServerConfig, ServerConnection, StreamOwned};
use rustls_pki_types::pem::PemObject;
use rustls_pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer};

/// How long a TLS handshake may take before the connection is dropped.
const HANDSHAKE_LIMIT: Duration = Duration::from_secs(4);

/// Where the certificate came from; printed at start so the operator knows
/// which of U-002's options is in force.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Source {
    /// `--cert` / `--key` (option A).
    Operator,
    /// `--self-signed` (option B, the fallback), kept at this path.
    SelfSigned(Utf8PathBuf),
}

impl Source {
    /// One line naming the source, for the host terminal and the JSON report.
    #[must_use]
    pub fn label(&self) -> String {
        match self {
            Self::Operator => "operator-supplied (U-002 option A)".to_owned(),
            Self::SelfSigned(p) => format!(
                "self-signed at {p} (U-002 option B, the fallback: every device shows a browser warning; compare the fingerprint)"
            ),
        }
    }
}

/// A loaded server configuration and the leaf certificate's fingerprint.
pub struct Tls {
    config: Arc<ServerConfig>,
    /// SHA-256 of the leaf certificate's DER, `AA:BB:…`.
    pub fingerprint: String,
    pub source: Source,
}

fn config(
    chain: Vec<CertificateDer<'static>>,
    key: PrivateKeyDer<'static>,
) -> Result<ServerConfig, String> {
    let provider = Arc::new(rustls::crypto::ring::default_provider());
    let mut c = ServerConfig::builder_with_provider(provider)
        .with_safe_default_protocol_versions()
        .map_err(|e| format!("ui.tls-config: {e}"))?
        .with_no_client_auth()
        .with_single_cert(chain, key)
        .map_err(|e| {
            format!(
                "ui.tls-certificate: the certificate and key do not make a server identity: {e}"
            )
        })?;
    c.alpn_protocols = vec![b"http/1.1".to_vec()];
    Ok(c)
}

/// The colon-separated SHA-256 of a certificate's DER.
#[must_use]
pub fn fingerprint(der: &[u8]) -> String {
    let hex = openwarrant_compiler::sha256_hex(der).to_ascii_uppercase();
    hex.as_bytes()
        .chunks(2)
        .map(|c| String::from_utf8_lossy(c).into_owned())
        .collect::<Vec<_>>()
        .join(":")
}

impl Tls {
    /// U-002 option A: an operator's PEM certificate chain and private key.
    pub fn operator(cert: &Utf8Path, key: &Utf8Path) -> Result<Self, String> {
        let chain: Vec<CertificateDer<'static>> = CertificateDer::pem_file_iter(cert.as_std_path())
            .map_err(|e| format!("ui.tls-certificate: cannot read {cert}: {e}"))?
            .collect::<Result<_, _>>()
            .map_err(|e| {
                format!("ui.tls-certificate: {cert} is not a PEM certificate chain: {e}")
            })?;
        let Some(leaf) = chain.first() else {
            return Err(format!("ui.tls-certificate: {cert} holds no certificate"));
        };
        let fingerprint = fingerprint(leaf.as_ref());
        let key = PrivateKeyDer::from_pem_file(key.as_std_path())
            .map_err(|e| format!("ui.tls-key: cannot read a PEM private key from {key}: {e}"))?;
        Ok(Self {
            config: Arc::new(config(chain, key)?),
            fingerprint,
            source: Source::Operator,
        })
    }

    /// U-002 option B, the fallback: a self-signed certificate for `name`,
    /// made once and kept under `dir` (mode 0600), remade after a year.
    pub fn self_signed(name: &str, dir: &Utf8Path) -> Result<Self, String> {
        let safe: String = name
            .chars()
            .map(|c| {
                if c.is_ascii_alphanumeric() || c == '.' || c == '-' {
                    c
                } else {
                    '_'
                }
            })
            .collect();
        let cert_path = dir.join(format!("{safe}.cert.der"));
        let key_path = dir.join(format!("{safe}.key.der"));
        let fresh = std::fs::metadata(&cert_path)
            .and_then(|m| m.modified())
            .ok()
            .and_then(|t| t.elapsed().ok())
            .is_some_and(|age| age < Duration::from_secs(360 * 86_400));
        let (cert, key) = match (fresh, std::fs::read(&cert_path), std::fs::read(&key_path)) {
            (true, Ok(c), Ok(k)) => (c, k),
            _ => {
                let (c, k) = generate(name)?;
                super::pairing::write_private(&key_path, &k)?;
                super::pairing::write_private(&cert_path, &c)?;
                (c, k)
            }
        };
        let fingerprint = fingerprint(&cert);
        let key = PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key));
        Ok(Self {
            config: Arc::new(config(vec![CertificateDer::from(cert)], key)?),
            fingerprint,
            source: Source::SelfSigned(cert_path),
        })
    }

    /// Complete a TLS handshake on an accepted connection within the limit.
    /// Anything else — plain HTTP, a stalled client — is an error, and the
    /// caller drops the connection without writing a byte of HTTP.
    pub fn accept(
        &self,
        tcp: TcpStream,
    ) -> Result<StreamOwned<ServerConnection, TcpStream>, String> {
        let mut tcp = tcp;
        tcp.set_nonblocking(false).map_err(|e| e.to_string())?;
        tcp.set_read_timeout(Some(Duration::from_secs(1)))
            .map_err(|e| e.to_string())?;
        tcp.set_write_timeout(Some(Duration::from_secs(2)))
            .map_err(|e| e.to_string())?;
        let mut conn =
            ServerConnection::new(Arc::clone(&self.config)).map_err(|e| e.to_string())?;
        let deadline = Instant::now() + HANDSHAKE_LIMIT;
        while conn.is_handshaking() {
            if Instant::now() >= deadline {
                return Err("handshake not completed in time".to_owned());
            }
            match conn.complete_io(&mut tcp) {
                Ok((0, 0)) => return Err("the peer closed during the handshake".to_owned()),
                Ok(_) => {}
                // A pause longer than one read's timeout is not a failed
                // handshake; HANDSHAKE_LIMIT is the bound (t-26ca).
                Err(e) if super::stalled(&e) => {}
                Err(e) => return Err(e.to_string()),
            }
        }
        Ok(StreamOwned::new(conn, tcp))
    }
}

// ---- the fallback's certificate: a minimal DER writer ----------------------
//
// Only what a self-signed P-256 server certificate needs: X.509 v3, a random
// positive serial, ecdsa-with-SHA256, CN and subjectAltName for `name`, and
// extendedKeyUsage serverAuth. The unit test below hands the result to
// rustls on both sides of a handshake, so a malformed encoding fails there.

fn tlv(tag: u8, parts: &[&[u8]]) -> Vec<u8> {
    let n: usize = parts.iter().map(|p| p.len()).sum();
    let mut out = vec![tag];
    if n < 0x80 {
        out.push(n as u8);
    } else if n < 0x100 {
        out.extend([0x81, n as u8]);
    } else {
        out.extend([0x82, (n >> 8) as u8, n as u8]);
    }
    for p in parts {
        out.extend_from_slice(p);
    }
    out
}

const SEQ: u8 = 0x30;
const SET: u8 = 0x31;
/// ecdsa-with-SHA256, 1.2.840.10045.4.3.2
const OID_ECDSA_SHA256: &[u8] = &[0x06, 0x08, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x04, 0x03, 0x02];
/// id-ecPublicKey 1.2.840.10045.2.1, prime256v1 1.2.840.10045.3.1.7
const OID_EC_PUBLIC_KEY: &[u8] = &[0x06, 0x07, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x02, 0x01];
const OID_P256: &[u8] = &[0x06, 0x08, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x03, 0x01, 0x07];
const OID_CN: &[u8] = &[0x06, 0x03, 0x55, 0x04, 0x03];
const OID_SAN: &[u8] = &[0x06, 0x03, 0x55, 0x1d, 0x11];
const OID_EKU: &[u8] = &[0x06, 0x03, 0x55, 0x1d, 0x25];
const OID_SERVER_AUTH: &[u8] = &[0x06, 0x08, 0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x01];

fn utc_time(unix: i64) -> Result<Vec<u8>, String> {
    let t = chrono::DateTime::<chrono::Utc>::from_timestamp(unix, 0)
        .ok_or("ui.tls-certificate: the clock is out of range")?;
    Ok(tlv(
        0x17,
        &[t.format("%y%m%d%H%M%SZ").to_string().as_bytes()],
    ))
}

/// A self-signed certificate and its PKCS#8 key, both DER.
fn generate(name: &str) -> Result<(Vec<u8>, Vec<u8>), String> {
    use ring::rand::SecureRandom;
    use ring::signature::{ECDSA_P256_SHA256_ASN1_SIGNING, EcdsaKeyPair, KeyPair};
    let rng = ring::rand::SystemRandom::new();
    let pkcs8 = EcdsaKeyPair::generate_pkcs8(&ECDSA_P256_SHA256_ASN1_SIGNING, &rng)
        .map_err(|_| "ui.tls-certificate: could not generate a key")?;
    let pair = EcdsaKeyPair::from_pkcs8(&ECDSA_P256_SHA256_ASN1_SIGNING, pkcs8.as_ref(), &rng)
        .map_err(|_| "ui.tls-certificate: could not load the generated key")?;
    let mut serial = [0u8; 16];
    rng.fill(&mut serial)
        .map_err(|_| "ui.tls-certificate: no random source")?;
    serial[0] = (serial[0] & 0x7f) | 0x01;
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|e| e.to_string())?
        .as_secs() as i64;
    let alg = tlv(SEQ, &[OID_ECDSA_SHA256]);
    let cn = format!("war ui {name}");
    let dn = tlv(
        SEQ,
        &[&tlv(
            SET,
            &[&tlv(SEQ, &[OID_CN, &tlv(0x0c, &[cn.as_bytes()])])],
        )],
    );
    let validity = tlv(
        SEQ,
        &[&utc_time(now - 86_400)?, &utc_time(now + 397 * 86_400)?],
    );
    let mut point = vec![0u8];
    point.extend_from_slice(pair.public_key().as_ref());
    let spki = tlv(
        SEQ,
        &[
            &tlv(SEQ, &[OID_EC_PUBLIC_KEY, OID_P256]),
            &tlv(0x03, &[&point]),
        ],
    );
    let general_name = match name.trim_matches(['[', ']']).parse::<std::net::IpAddr>() {
        Ok(std::net::IpAddr::V4(ip)) => tlv(0x87, &[&ip.octets()]),
        Ok(std::net::IpAddr::V6(ip)) => tlv(0x87, &[&ip.octets()]),
        Err(_) => tlv(0x82, &[name.as_bytes()]),
    };
    let san = tlv(SEQ, &[OID_SAN, &tlv(0x04, &[&tlv(SEQ, &[&general_name])])]);
    let eku = tlv(
        SEQ,
        &[OID_EKU, &tlv(0x04, &[&tlv(SEQ, &[OID_SERVER_AUTH])])],
    );
    let extensions = tlv(0xa3, &[&tlv(SEQ, &[&san, &eku])]);
    let tbs = tlv(
        SEQ,
        &[
            &[0xa0, 0x03, 0x02, 0x01, 0x02],
            &tlv(0x02, &[&serial]),
            &alg,
            &dn,
            &validity,
            &dn,
            &spki,
            &extensions,
        ],
    );
    let sig = pair
        .sign(&rng, &tbs)
        .map_err(|_| "ui.tls-certificate: could not sign the certificate")?;
    let mut bits = vec![0u8];
    bits.extend_from_slice(sig.as_ref());
    let cert = tlv(SEQ, &[&tbs, &alg, &tlv(0x03, &[&bits])]);
    Ok((cert, pkcs8.as_ref().to_vec()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::{Read, Write};

    #[test]
    fn der_lengths_use_the_long_form_past_127() {
        assert_eq!(tlv(0x04, &[&[0u8; 3]])[..2], [0x04, 3]);
        assert_eq!(tlv(0x04, &[&[0u8; 200]])[..3], [0x04, 0x81, 200]);
        assert_eq!(tlv(0x04, &[&[0u8; 300]])[..4], [0x04, 0x82, 0x01, 0x2c]);
    }

    /// The fallback's certificate completes a real handshake: a rustls
    /// client that trusts exactly it connects to a rustls server using it,
    /// for the name it was made for — and a client asking for another name
    /// is refused.
    #[test]
    fn a_self_signed_certificate_serves_its_name_and_no_other() {
        let (cert, key) = generate("war-host.test").unwrap();
        let server = Arc::new(
            config(
                vec![CertificateDer::from(cert.clone())],
                PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key)),
            )
            .unwrap(),
        );
        let handshake = |name: &'static str| -> Result<Vec<u8>, String> {
            let mut roots = rustls::RootCertStore::empty();
            roots.add(CertificateDer::from(cert.clone())).unwrap();
            let client = rustls::ClientConfig::builder_with_provider(Arc::new(
                rustls::crypto::ring::default_provider(),
            ))
            .with_safe_default_protocol_versions()
            .unwrap()
            .with_root_certificates(roots)
            .with_no_client_auth();
            let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
            let addr = listener.local_addr().unwrap();
            let config = Arc::clone(&server);
            let t = std::thread::spawn(move || {
                let (tcp, _) = listener.accept().unwrap();
                let tls = Tls {
                    config,
                    fingerprint: String::new(),
                    source: Source::Operator,
                };
                if let Ok(mut s) = tls.accept(tcp) {
                    let _ = s.write_all(b"ok");
                    let _ = s.flush();
                    s.conn.send_close_notify();
                    let _ = s.flush();
                }
            });
            let tcp = TcpStream::connect(addr).unwrap();
            let conn = rustls::ClientConnection::new(
                Arc::new(client),
                rustls_pki_types::ServerName::try_from(name).unwrap(),
            )
            .unwrap();
            let mut s = StreamOwned::new(conn, tcp);
            let mut got = Vec::new();
            let r = s
                .read_to_end(&mut got)
                .map(|_| got)
                .map_err(|e| e.to_string());
            t.join().unwrap();
            r
        };
        assert_eq!(handshake("war-host.test").unwrap(), b"ok");
        assert!(handshake("another.test").is_err());
    }

    #[test]
    fn an_ip_name_gets_an_ip_subject_alt_name() {
        let (cert, _) = generate("127.0.0.2").unwrap();
        // iPAddress [7] with the four octets.
        assert!(cert.windows(6).any(|w| w == [0x87, 4, 127, 0, 0, 2]));
    }

    #[test]
    fn fingerprints_are_colon_separated_sha256() {
        let f = fingerprint(b"x");
        assert_eq!(f.len(), 32 * 3 - 1);
        assert!(f.chars().all(|c| c == ':' || c.is_ascii_hexdigit()));
    }
}

// SPDX-License-Identifier: Apache-2.0
//! Devices for `war ui --lan` (OW-WAR-0139): pairing, credentials, nonces.
//!
//! A device credential is a session in OW-WAR-0138's sense. It is never an
//! authority to sign: a paired device reads the program, runs `auto`
//! remedies and can ask for a signature at the host (U-001 option A).
//!
//! - **Pairing.** The host prints a link carrying a single-use code (and the
//!   certificate's fingerprint, for the human to compare). A code works once
//!   and for five minutes. Presenting it asks the human at the host's
//!   terminal — naming the device's address and user agent — and only a `y`
//!   typed there issues a credential. No answer, `n`, or no terminal at all
//!   issues none, each refused by name.
//! - **Credential.** 256 bits from the OS, sent once as a `Secure; HttpOnly;
//!   SameSite=Strict` cookie. The server keeps only its SHA-256, with the
//!   device's address, user agent and expiry, in the per-user state
//!   directory (`$XDG_STATE_HOME/openwarrant/ui-devices.json`, mode 0600) —
//!   never under a repository. It is read on every request, so `war ui
//!   devices --revoke <id>` in another terminal takes effect at once.
//! - **Nonces.** Every act a device starts carries a nonce the server issued
//!   to that device; a nonce is spent on first use, and a second use is
//!   refused.
//!
//! Local state, not a record: nothing here is committed, and deleting the
//! file revokes every device.

use std::collections::{BTreeMap, HashSet};
use std::io::{BufRead, Write};
use std::sync::Mutex;
use std::sync::mpsc::{Receiver, RecvTimeoutError};
use std::time::{Duration, Instant};

use camino::{Utf8Path, Utf8PathBuf};
use serde::{Deserialize, Serialize};

/// The cookie that carries a device credential. `__Host-` makes the browser
/// refuse it unless it is `Secure`, has `Path=/` and names no domain.
pub const COOKIE: &str = "__Host-war_device";

/// How long a pairing code lives.
pub const CODE_TTL: Duration = Duration::from_secs(300);
/// How long the host's human has to answer.
pub const ANSWER_TTL: Duration = Duration::from_secs(60);
/// How long a credential lives.
pub const DEVICE_TTL: Duration = Duration::from_secs(30 * 86_400);
/// How long an issued nonce stays spendable, and how many a device may hold.
const NONCE_TTL: Duration = Duration::from_secs(300);
const NONCES_PER_DEVICE: usize = 16;

fn sha(s: &str) -> String {
    openwarrant_compiler::sha256_hex(s.as_bytes())
}

fn now_unix() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_secs() as i64)
}

fn rfc3339(unix: i64) -> String {
    chrono::DateTime::<chrono::Utc>::from_timestamp(unix, 0)
        .map_or_else(String::new, |t| t.format("%Y-%m-%dT%H:%M:%SZ").to_string())
}

/// `$XDG_STATE_HOME/openwarrant`, else `~/.local/state/openwarrant`.
pub fn state_dir() -> Result<Utf8PathBuf, String> {
    let base = std::env::var("XDG_STATE_HOME")
        .ok()
        .filter(|v| v.starts_with('/'))
        .map(Utf8PathBuf::from)
        .or_else(|| {
            std::env::var("HOME")
                .ok()
                .filter(|h| !h.is_empty())
                .map(|h| Utf8PathBuf::from(h).join(".local/state"))
        })
        .ok_or("ui.devices-no-state: neither XDG_STATE_HOME nor HOME is set")?;
    Ok(base.join("openwarrant"))
}

/// Write `bytes` to `path` as a private file: created 0600 in a 0700
/// directory, fsynced, renamed into place.
#[cfg(unix)]
pub fn write_private(path: &Utf8Path, bytes: &[u8]) -> Result<(), String> {
    use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
    let dir = path
        .parent()
        .ok_or("ui.devices-path: no parent directory")?;
    std::fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(dir)
        .map_err(|e| format!("ui.devices-write: {dir}: {e}"))?;
    let tmp = dir.join(format!(
        ".{}.{}.tmp",
        path.file_name().unwrap_or("state"),
        std::process::id()
    ));
    let _ = std::fs::remove_file(&tmp);
    let mut f = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(&tmp)
        .map_err(|e| format!("ui.devices-write: {tmp}: {e}"))?;
    f.write_all(bytes)
        .and_then(|()| f.sync_all())
        .map_err(|e| format!("ui.devices-write: {tmp}: {e}"))?;
    std::fs::rename(&tmp, path).map_err(|e| format!("ui.devices-write: {path}: {e}"))
}

#[cfg(not(unix))]
pub fn write_private(_path: &Utf8Path, _bytes: &[u8]) -> Result<(), String> {
    Err("ui.lan-unsupported: device state needs a Unix file mode".to_owned())
}

/// One paired device. `credential_sha256` is all that is kept of the
/// credential.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Device {
    pub id: String,
    /// The repository root the server was serving.
    pub root: String,
    pub credential_sha256: String,
    pub address: String,
    pub user_agent: String,
    pub paired_at: i64,
    pub expires_at: i64,
    #[serde(default)]
    pub revoked_at: Option<i64>,
}

impl Device {
    /// `active`, `revoked` or `expired`, now.
    #[must_use]
    pub fn state(&self) -> &'static str {
        if self.revoked_at.is_some() {
            "revoked"
        } else if now_unix() >= self.expires_at {
            "expired"
        } else {
            "active"
        }
    }

    /// The row `war ui devices` prints and reports.
    #[must_use]
    pub fn row(&self) -> serde_json::Value {
        serde_json::json!({
            "id": self.id, "state": self.state(), "address": self.address,
            "user_agent": self.user_agent, "paired_at": rfc3339(self.paired_at),
            "expires_at": rfc3339(self.expires_at),
            "revoked_at": self.revoked_at.map(rfc3339),
        })
    }

    /// How a request from this device is named on the host.
    #[must_use]
    pub fn label(&self) -> String {
        format!("device {} ({})", self.id, self.address)
    }
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct DeviceFile {
    schema: String,
    devices: Vec<Device>,
}

const FILE_SCHEMA: &str = "oh.war/ui-devices/v1 (local state, not a record)";

/// Why a request's credential was not accepted; each is a 401.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AuthRefusal {
    Missing,
    Unknown,
    Revoked,
    Expired,
    Unreadable,
}

impl AuthRefusal {
    #[must_use]
    pub fn message(self) -> &'static str {
        match self {
            Self::Missing => {
                "ui.device-required: this device is not paired; open a pairing link from the host"
            }
            Self::Unknown => "ui.device-unknown: no paired device holds this credential",
            Self::Revoked => "ui.device-revoked: this device's pairing was revoked at the host",
            Self::Expired => "ui.device-expired: this device's pairing expired; pair it again",
            Self::Unreadable => "ui.device-state: the host could not read its device file",
        }
    }
}

/// The device file for one repository's server.
pub struct Store {
    pub path: Utf8PathBuf,
    root: String,
}

impl Store {
    /// The per-user device file, refused when it would sit under `root`.
    pub fn open(root: &Utf8Path) -> Result<Self, String> {
        let path = state_dir()?.join("ui-devices.json");
        Self::at(path, root)
    }

    fn at(path: Utf8PathBuf, root: &Utf8Path) -> Result<Self, String> {
        let canon = |p: &Utf8Path| -> Utf8PathBuf {
            // The deepest existing ancestor, canonicalized, so a symlinked
            // state directory into the repository is seen for what it is.
            let mut cur = p.to_path_buf();
            let mut tail = Vec::new();
            loop {
                if let Ok(c) = cur.canonicalize_utf8() {
                    let mut c = c;
                    for t in tail.iter().rev() {
                        c.push(t);
                    }
                    return c;
                }
                match (cur.parent(), cur.file_name()) {
                    (Some(parent), Some(name)) => {
                        tail.push(name.to_owned());
                        cur = parent.to_path_buf();
                    }
                    _ => return p.to_path_buf(),
                }
            }
        };
        let root_c = canon(root);
        if canon(&path).starts_with(&root_c) {
            return Err(format!(
                "ui.devices-in-repository: the device file {path} would be under the repository {root}; \
                 device state is per-user and never recorded — set XDG_STATE_HOME outside it"
            ));
        }
        Ok(Self {
            path,
            root: root_c.to_string(),
        })
    }

    fn read(&self) -> Result<DeviceFile, String> {
        match std::fs::read(&self.path) {
            Ok(bytes) => {
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt;
                    let mode = std::fs::metadata(&self.path)
                        .map_err(|e| e.to_string())?
                        .permissions()
                        .mode();
                    if mode & 0o077 != 0 {
                        return Err(format!(
                            "ui.devices-mode: {} is mode {:o}; it must be 0600",
                            self.path,
                            mode & 0o777
                        ));
                    }
                }
                serde_json::from_slice(&bytes)
                    .map_err(|e| format!("ui.devices-unreadable: {}: {e}", self.path))
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(DeviceFile::default()),
            Err(e) => Err(format!("ui.devices-unreadable: {}: {e}", self.path)),
        }
    }

    /// Read, change and write the file under an exclusive lock, so a
    /// revocation in another process is never lost to a pairing here.
    #[cfg(unix)]
    fn update<R>(&self, f: impl FnOnce(&mut DeviceFile) -> Result<R, String>) -> Result<R, String> {
        use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
        let dir = self.path.parent().ok_or("ui.devices-path: no parent")?;
        std::fs::DirBuilder::new()
            .recursive(true)
            .mode(0o700)
            .create(dir)
            .map_err(|e| format!("ui.devices-write: {dir}: {e}"))?;
        let lock = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .mode(0o600)
            .open(self.path.with_extension("lock"))
            .map_err(|e| format!("ui.devices-lock: {e}"))?;
        rustix::fs::flock(&lock, rustix::fs::FlockOperation::LockExclusive)
            .map_err(|e| format!("ui.devices-lock: {e}"))?;
        let mut file = self.read()?;
        let r = f(&mut file)?;
        file.schema = FILE_SCHEMA.to_owned();
        let bytes = serde_json::to_vec_pretty(&file).map_err(|e| e.to_string())?;
        write_private(&self.path, &bytes)?;
        Ok(r)
    }

    #[cfg(not(unix))]
    fn update<R>(
        &self,
        _f: impl FnOnce(&mut DeviceFile) -> Result<R, String>,
    ) -> Result<R, String> {
        Err("ui.lan-unsupported: device state needs a Unix file mode".to_owned())
    }

    /// Record a new device and return it with its credential — the only
    /// time the credential exists outside the device.
    pub fn issue(
        &self,
        address: &str,
        user_agent: &str,
        ttl: Duration,
    ) -> Result<(Device, String), String> {
        let credential = super::token().map_err(|e| e.to_string())?;
        let id = super::token().map_err(|e| e.to_string())?[..8].to_owned();
        let now = now_unix();
        let device = Device {
            id,
            root: self.root.clone(),
            credential_sha256: sha(&credential),
            address: address.to_owned(),
            user_agent: user_agent.to_owned(),
            paired_at: now,
            expires_at: now + ttl.as_secs() as i64,
            revoked_at: None,
        };
        let d = device.clone();
        self.update(move |f| {
            f.devices.push(d);
            Ok(())
        })?;
        Ok((device, credential))
    }

    /// The device holding `credential`, if it is active for this repository.
    pub fn authenticate(&self, credential: Option<&str>) -> Result<Device, AuthRefusal> {
        let Some(c) = credential.filter(|c| !c.is_empty()) else {
            return Err(AuthRefusal::Missing);
        };
        let h = sha(c);
        let file = self.read().map_err(|_| AuthRefusal::Unreadable)?;
        let d = file
            .devices
            .into_iter()
            .find(|d| d.root == self.root && super::same(&d.credential_sha256, &h))
            .ok_or(AuthRefusal::Unknown)?;
        match d.state() {
            "revoked" => Err(AuthRefusal::Revoked),
            "expired" => Err(AuthRefusal::Expired),
            _ => Ok(d),
        }
    }

    /// Every device paired for this repository, oldest first.
    pub fn list(&self) -> Result<Vec<Device>, String> {
        Ok(self
            .read()?
            .devices
            .into_iter()
            .filter(|d| d.root == self.root)
            .collect())
    }

    /// Revoke one device by id; revoking twice is refused by name.
    pub fn revoke(&self, id: &str) -> Result<Device, String> {
        let root = self.root.clone();
        self.update(|f| {
            let d = f
                .devices
                .iter_mut()
                .find(|d| d.root == root && d.id == id)
                .ok_or_else(|| {
                    format!("ui.device-unknown: no device {id} is paired for this repository")
                })?;
            if d.revoked_at.is_some() {
                return Err(format!("ui.device-revoked: device {id} is already revoked"));
            }
            d.revoked_at = Some(now_unix());
            Ok(d.clone())
        })
    }
}

/// Why a pairing code was refused.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CodeRefusal {
    Unknown,
    Used,
    Expired,
}

impl CodeRefusal {
    #[must_use]
    pub fn message(self) -> &'static str {
        match self {
            Self::Unknown => "pair.code-unknown: this is not the host's pairing code",
            Self::Used => {
                "pair.code-used: this pairing code was already used; the host's terminal shows a new link"
            }
            Self::Expired => {
                "pair.code-expired: this pairing code expired; the host's terminal shows a new link"
            }
        }
    }
}

/// The outstanding code's hash and deadline, and every spent code's hash.
type CodeState = (Option<(String, Instant)>, HashSet<String>);

/// The single outstanding pairing code, and every code already spent.
pub struct Codes {
    inner: Mutex<CodeState>,
    ttl: Duration,
}

impl Codes {
    #[must_use]
    pub fn new(ttl: Duration) -> Self {
        Self {
            inner: Mutex::new((None, HashSet::new())),
            ttl,
        }
    }

    #[must_use]
    pub fn ttl(&self) -> Duration {
        self.ttl
    }

    /// A fresh code, replacing any outstanding one (which is then spent).
    pub fn fresh(&self) -> Result<String, String> {
        let code = super::token().map_err(|e| e.to_string())?[..32].to_owned();
        let mut g = self.inner.lock().map_err(|_| "pairing state poisoned")?;
        if let Some((old, _)) = g.0.take() {
            g.1.insert(old);
        }
        g.0 = Some((sha(&code), Instant::now() + self.ttl));
        Ok(code)
    }

    /// Spend `code`. Only the outstanding, unexpired code is accepted, once.
    pub fn take(&self, code: &str) -> Result<(), CodeRefusal> {
        let h = sha(code);
        let mut g = self.inner.lock().map_err(|_| CodeRefusal::Unknown)?;
        if g.1.contains(&h) {
            return Err(CodeRefusal::Used);
        }
        match g.0.take() {
            Some((cur, until)) if super::same(&cur, &h) => {
                g.1.insert(cur);
                if Instant::now() >= until {
                    Err(CodeRefusal::Expired)
                } else {
                    Ok(())
                }
            }
            other => {
                g.0 = other;
                Err(CodeRefusal::Unknown)
            }
        }
    }
}

/// What the human at the host said.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Answer {
    Yes,
    No,
    TimedOut,
    NoTty,
}

/// The host's terminal (`/dev/tty`), where every pairing is confirmed. One
/// question at a time; lines typed before a question are discarded, so a
/// stale `y` never answers a later pairing.
#[derive(Default)]
pub struct HostTty {
    io: Mutex<Option<(std::fs::File, Receiver<String>)>>,
}

impl HostTty {
    fn open() -> Option<(std::fs::File, Receiver<String>)> {
        let tty = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open("/dev/tty")
            .ok()?;
        let reader = tty.try_clone().ok()?;
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            for line in std::io::BufReader::new(reader).lines() {
                let Ok(line) = line else { break };
                if tx.send(line).is_err() {
                    break;
                }
            }
        });
        Some((tty, rx))
    }

    /// Ask `question` at the host terminal and wait up to `timeout`.
    pub fn ask(&self, question: &str, timeout: Duration) -> Answer {
        let Ok(mut g) = self.io.lock() else {
            return Answer::NoTty;
        };
        if g.is_none() {
            *g = Self::open();
        }
        let Some((tty, rx)) = g.as_mut() else {
            return Answer::NoTty;
        };
        while rx.try_recv().is_ok() {}
        if tty
            .write_all(question.as_bytes())
            .and_then(|()| tty.flush())
            .is_err()
        {
            *g = None;
            return Answer::NoTty;
        }
        match rx.recv_timeout(timeout) {
            Ok(line) => {
                let a = line.trim().to_ascii_lowercase();
                if a == "y" || a == "yes" {
                    Answer::Yes
                } else {
                    Answer::No
                }
            }
            Err(RecvTimeoutError::Timeout) => {
                let _ = tty.write_all(b"\n  (no answer; not paired)\n");
                Answer::TimedOut
            }
            Err(RecvTimeoutError::Disconnected) => {
                *g = None;
                Answer::NoTty
            }
        }
    }
}

/// Why a nonce was refused.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NonceRefusal {
    Used,
    NotIssued,
    Expired,
}

impl NonceRefusal {
    #[must_use]
    pub fn status(self) -> &'static str {
        match self {
            Self::Used => "409 Conflict",
            Self::NotIssued | Self::Expired => "403 Forbidden",
        }
    }

    #[must_use]
    pub fn message(self) -> &'static str {
        match self {
            Self::Used => "act.nonce-used: this nonce was already spent; nothing ran",
            Self::NotIssued => {
                "act.nonce-unknown: no such nonce was issued to this device; nothing ran"
            }
            Self::Expired => "act.nonce-expired: this nonce expired; ask for a new one",
        }
    }
}

/// Issued nonces by hash → (device, when), and every spent nonce's hash.
type NonceState = (BTreeMap<String, (String, Instant)>, HashSet<String>);

/// Single-use act nonces, per device.
#[derive(Default)]
pub struct Nonces {
    inner: Mutex<NonceState>,
}

impl Nonces {
    /// A fresh nonce for `device`; its oldest is dropped past the bound.
    pub fn issue(&self, device: &str) -> Result<String, String> {
        let n = super::token().map_err(|e| e.to_string())?;
        let mut g = self.inner.lock().map_err(|_| "nonce state poisoned")?;
        let mut mine: Vec<(String, Instant)> =
            g.0.iter()
                .filter(|(_, (d, _))| d == device)
                .map(|(k, (_, t))| (k.clone(), *t))
                .collect();
        if mine.len() >= NONCES_PER_DEVICE {
            mine.sort_by_key(|(_, t)| *t);
            for (k, _) in mine.iter().take(mine.len() + 1 - NONCES_PER_DEVICE) {
                g.0.remove(k);
            }
        }
        g.0.insert(sha(&n), (device.to_owned(), Instant::now()));
        Ok(n)
    }

    /// Spend `nonce` for `device`: once, only if issued to it, only fresh.
    pub fn spend(&self, device: &str, nonce: &str) -> Result<(), NonceRefusal> {
        let h = sha(nonce);
        let mut g = self.inner.lock().map_err(|_| NonceRefusal::NotIssued)?;
        if g.1.contains(&h) {
            return Err(NonceRefusal::Used);
        }
        match g.0.get(&h) {
            Some((d, _)) if d == device => {}
            _ => return Err(NonceRefusal::NotIssued),
        }
        let (_, at) = g.0.remove(&h).ok_or(NonceRefusal::NotIssued)?;
        g.1.insert(h);
        if at.elapsed() > NONCE_TTL {
            return Err(NonceRefusal::Expired);
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn scratch() -> (Utf8PathBuf, Utf8PathBuf) {
        let base = Utf8PathBuf::from(std::env::temp_dir().to_string_lossy().into_owned())
            .join(format!("war-pairing-{}", super::super::token().unwrap()));
        let repo = base.join("repo");
        std::fs::create_dir_all(&repo).unwrap();
        (base, repo)
    }

    #[test]
    fn a_credential_is_stored_only_as_its_hash_in_a_private_file() {
        let (base, repo) = scratch();
        let store = Store::at(base.join("state/ui-devices.json"), &repo).unwrap();
        let (d, cred) = store.issue("192.0.2.7", "phone", DEVICE_TTL).unwrap();
        let text = std::fs::read_to_string(&store.path).unwrap();
        assert!(!text.contains(&cred));
        assert!(text.contains(&d.credential_sha256));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(&store.path).unwrap().permissions().mode();
            assert_eq!(mode & 0o777, 0o600);
        }
        assert_eq!(store.authenticate(Some(&cred)).unwrap().id, d.id);
        assert_eq!(store.authenticate(None), Err(AuthRefusal::Missing));
        assert_eq!(store.authenticate(Some("00")), Err(AuthRefusal::Unknown));
        store.revoke(&d.id).unwrap();
        assert_eq!(store.authenticate(Some(&cred)), Err(AuthRefusal::Revoked));
        assert!(store.revoke(&d.id).is_err());
        let (_, old) = store.issue("192.0.2.8", "old", Duration::ZERO).unwrap();
        assert_eq!(store.authenticate(Some(&old)), Err(AuthRefusal::Expired));
        std::fs::remove_dir_all(&base).unwrap();
    }

    #[test]
    fn a_device_file_under_the_repository_is_refused() {
        let (base, repo) = scratch();
        let e = Store::at(repo.join(".state/ui-devices.json"), &repo)
            .err()
            .unwrap();
        assert!(e.starts_with("ui.devices-in-repository"), "{e}");
        std::fs::remove_dir_all(&base).unwrap();
    }

    #[test]
    fn a_pairing_code_works_once_and_not_after_expiry() {
        let codes = Codes::new(Duration::from_secs(60));
        let c = codes.fresh().unwrap();
        assert_eq!(codes.take("nope"), Err(CodeRefusal::Unknown));
        assert_eq!(codes.take(&c), Ok(()));
        assert_eq!(codes.take(&c), Err(CodeRefusal::Used));
        let short = Codes::new(Duration::ZERO);
        let c = short.fresh().unwrap();
        assert_eq!(short.take(&c), Err(CodeRefusal::Expired));
        assert_eq!(short.take(&c), Err(CodeRefusal::Used));
        // A fresh code retires the outstanding one.
        let codes = Codes::new(Duration::from_secs(60));
        let a = codes.fresh().unwrap();
        let b = codes.fresh().unwrap();
        assert_eq!(codes.take(&a), Err(CodeRefusal::Used));
        assert_eq!(codes.take(&b), Ok(()));
    }

    #[test]
    fn a_nonce_is_spent_once_and_only_by_its_device() {
        let n = Nonces::default();
        let a = n.issue("dev-a").unwrap();
        assert_eq!(n.spend("dev-b", &a), Err(NonceRefusal::NotIssued));
        assert_eq!(n.spend("dev-a", &a), Ok(()));
        assert_eq!(n.spend("dev-a", &a), Err(NonceRefusal::Used));
        assert_eq!(n.spend("dev-a", "never"), Err(NonceRefusal::NotIssued));
        let many: Vec<String> = (0..NONCES_PER_DEVICE + 2)
            .map(|_| n.issue("dev-a").unwrap())
            .collect();
        assert_eq!(n.spend("dev-a", &many[0]), Err(NonceRefusal::NotIssued));
        assert_eq!(n.spend("dev-a", many.last().unwrap()), Ok(()));
    }
}

// war ui — the page. Every value from the server is written with
// textContent, never parsed as HTML, so a record cannot inject markup. The
// session token arrives in the URL fragment, moves into this closure, and
// the fragment is cleared: it is never in a cookie, storage or a request
// URL. Acts send a row id; the server decides what runs.
//
// On the LAN (`war ui --lan`, https) there is no token: a paired device
// carries an HttpOnly cookie this script never sees, every act also sends a
// single-use nonce from the server, and a signing row shows only its verdict
// and the command to run at the host — this device can ask, never sign.
//
// Tickets (t-67ed): the first page. On loopback an open item carries Claim
// and Done, which POST {act, target[, note]} to /api/ticket; the server runs
// the same ticket commands the CLI does. On the LAN the page shows no ticket
// buttons, and the server refuses the route act.host-only regardless.
"use strict";
(() => {
  const params = new URLSearchParams(location.hash.slice(1));
  const token = params.get("t") || "";
  const lan = location.protocol === "https:";
  const pairCode = params.get("pair") || "";
  const pairFp = params.get("fp") || "";
  let page = params.get("p") || "tickets";
  history.replaceState(null, "", location.pathname + "#p=" + page);
  let version = null;

  const $ = (id) => document.getElementById(id);
  const el = (tag, attrs, ...kids) => {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (k === "class") n.className = v;
      else if (k === "text") n.textContent = v;
      else n.setAttribute(k, v);
    }
    for (const k of kids) if (k != null) n.append(k instanceof Node ? k : document.createTextNode(String(k)));
    return n;
  };
  const code = (s) => el("code", { text: s });
  // Tickets leads the navigation. The link is added here rather than in
  // index.html so the loopback page's bytes stay those OW-WAR-0139 OBL-005
  // pins; the page is the same either way.
  $("nav").prepend(el("a", { href: "#p=tickets", "data-page": "tickets", text: "Tickets" }));
  const api = async (path, init) => {
    const r = await fetch("/api/" + path, {
      ...init,
      headers: lan ? { ...(init && init.headers) } : { Authorization: "Bearer " + token, ...(init && init.headers) },
      cache: "no-store",
      credentials: lan ? "same-origin" : "omit",
    });
    if (r.status === 401) throw new Error(lan
      ? ((await r.text()) || "this device is not paired") + " — open a pairing link printed by `war ui --lan` at the host"
      : "session token missing or wrong — open the link `war ui` printed");
    if (!r.ok && r.status !== 202) throw new Error((await r.text()) || r.statusText);
    return r.json();
  };
  const rungBadge = (rung) => {
    const cls = rung === "resolved" ? "ok" : rung === "invalid" ? "bad" : rung === "draft" ? "warn" : "";
    return el("span", { class: "badge " + cls, text: rung || "?" });
  };
  const table = (head, rows) =>
    el("div", { class: "table-wrap" },
      el("table", {},
        el("thead", {}, el("tr", {}, ...head.map((h) => el("th", { text: h })))),
        el("tbody", {}, ...rows.map((cells) => el("tr", {}, ...cells.map((c) => el("td", {}, c)))))));

  const pages = {
    async tickets(main) {
      const d = await api("tickets");
      const list = d.tickets || [];
      main.append(el("h2", { text: "Tickets" }),
        el("p", { class: "muted", text: lan
          ? "Read-only on this device. Claim and finish tickets at the host (`war claim`, `war done`), or on its own `war ui` page."
          : "The ticket loop: claim an item, do it, mark it done. Nothing here needs a signature." }));
      if (!list.length) { main.append(el("p", { class: "muted" }, "No tickets yet — ", code("war create \"what this work accomplishes\" --item \"...\""))); return; }
      main.append(table(["ticket", "state", "done", "p", "title", "claimed by"], list.map((t) => {
        const r = t.ticket || {};
        return [code(r.id), el("span", { class: "badge " + (r.state === "done" ? "ok" : r.state === "in_progress" ? "warn" : ""), text: String(r.state || "").replace("_", " ") }),
          `${r.done}/${r.total}`, "p" + r.priority, r.title || "", (r.claims || []).map((c) => c.actor).join(", ")];
      })));
      for (const t of list) {
        const r = t.ticket || {};
        const box = el("section", { class: "phase" });
        box.append(el("div", { class: "head" }, el("strong", { text: r.id }), el("span", { text: r.title || "" }),
          el("span", { class: "badge", text: `${r.done}/${r.total} done` })));
        const items = t.items || [];
        if (!items.length) box.append(el("p", { class: "muted" }, "No items: the ticket is the work. ",
          lan || r.state === "done" ? null : ticketButton("claim", r.id, "Claim"), " ", lan || r.state === "done" ? null : ticketButton("done", r.id, "Done")));
        else box.append(table(["", "item", "", "command"], items.map((i) => [
          i.done ? "☑" : "☐",
          el("span", {}, i.text, i.id ? el("span", { class: "muted", text: " (" + i.id + ")" }) : null,
            i.done && i.done_by ? el("span", { class: "muted", text: " — done by " + i.done_by + (i.note ? ": " + i.note : "") }) : null),
          i.done || lan ? (i.ready ? el("span", { class: "badge", text: "ready" }) : "")
            : el("span", {}, i.ready ? ticketButton("claim", i.target, "Claim") : null, " ", ticketButton("done", i.target, "Done")),
          i.done ? "" : code("war claim " + i.target)])));
        if ((t.notes || []).length) box.append(el("h3", { text: "Notes" }), el("ul", {}, ...t.notes.map((n) => el("li", { text: n }))));
        main.append(box);
      }
    },
    async progress(main) {
      const d = await api("progress");
      const rm = d.roadmap || {};
      main.append(el("h2", { text: (rm.program || "Program") + " — roadmap" }),
        el("p", { class: "muted", text: rm.error ? rm.error
          : rm.accepted ? "revision " + rm.accepted_revision + " accepted"
          : "not an accepted revision" + (rm.pending_revision ? " — revision " + rm.pending_revision + " awaits one signature (Queue)" : "") }));
      const L = d.ladder || {};
      const total = (L.invalid || 0) + (L.draft || 0) + (L.ready_to_resolve || 0) + (L.would_satisfy || 0) + (L.resolved || 0);
      if (total) {
        const bar = el("div", { class: "bar", title: "resolved / ready / draft" });
        for (const [k, cls] of [["resolved", "resolved"], ["ready_to_resolve", "ready"], ["would_satisfy", "ready"], ["draft", "draft"]]) {
          const s = el("span", { class: cls }); s.style.width = ((L[k] || 0) * 100 / total) + "%"; bar.append(s);
        }
        main.append(bar, el("p", { class: "muted", text: `${L.resolved || 0} resolved · ${(L.ready_to_resolve || 0) + (L.would_satisfy || 0)} ready to resolve · ${L.draft || 0} draft · ${L.invalid || 0} invalid, of ${total}` }));
      }
      for (const p of d.phases || []) {
        const box = el("section", { class: "phase" });
        const achieved = String(p.achieved || "");
        box.append(el("div", { class: "head" },
          el("strong", { text: p.id }), el("span", { text: p.title }),
          p.tier ? el("span", { class: "badge", text: "tier " + p.tier }) : null,
          el("span", { class: "badge " + (achieved === "achieved" ? "ok" : achieved.startsWith("blocked") ? "warn" : ""), text: achieved })));
        box.append(el("p", { class: "muted" }, "exit: ", p.exit || "—"));
        if ((p.depends_on || []).length) box.append(el("p", { class: "muted", text: "after " + p.depends_on.join(", ") }));
        if ((p.members || []).length)
